# Vulnerability details

## Impact
The `_decodeUniswapV3Data` and `_decodeTransformERC20Data` functions are responsible for decoding data from the 0x API when either UniswapV3 and TransformERC20 is used.

If the input data is not properly validated, it could lead to serious security vulnerabilities. Malicious actors could potentially manipulate the decoded values by crafting the input data in a specific way, which could lead to unexpected behavior in the contract.

## Proof of Concept
Consider a scenario where a malicious actor provides `_data` that is shorter than expected. The `calldataload` function could read past the end of `_data`, resulting in undefined behavior. Similarly, if the input and output tokens are not valid addresses or if the `inputTokenAmount` is not a positive value, it could lead to issues elsewhere in the contract.

## Tools Used
-

## Recommended Mitigation Steps
The contract should validate the input data before using it. This includes checking that `_data` is long enough and that the decoded values are valid.

```sol
function _decodeUniswapV3Data(bytes calldata _data)
    internal
    pure
    returns (address inputToken, address outputToken, uint256 inputTokenAmount, address recipient, bytes4 selector)
{
    require(_data.length >= 160, "Data too short");

    uint256 encodedPathLength;
    assembly {
        let p := _data.offset
        selector := calldataload(p)
        p := add(p, 36) // Data: selector 4 + lenght data 32
        inputTokenAmount := calldataload(p)
        recipient := calldataload(add(p, 64))
        encodedPathLength := calldataload(add(p, 96)) // Get length of encodedPath (obtained through abi.encodePacked)
        inputToken := shr(96, calldataload(add(p, 128))) // Shift to the Right with 24 zeroes (12 bytes = 96 bits) to get address
        outputToken := shr(96, calldataload(add(p, add(encodedPathLength, 108)))) // Get last address of the hop
    }

    require(inputToken != address(0), "Invalid input token");
    require(outputToken != address(0), "Invalid output token");
    require(inputTokenAmount > 0, "Invalid token amount");
    require(recipient != address(0), "Invalid recipient");
}

function _decodeTransformERC20Data(bytes calldata _data)
    internal
    pure
    returns (address inputToken, address outputToken, uint256 inputTokenAmount, bytes4 selector)
{
    require(_data.length >= 96, "Data too short");

    assembly {
        let p := _data.offset
        selector := calldataload(p)
        inputToken := calldataload(add(p, 4)) // Read slot, selector 4 bytes
        outputToken := calldataload(add(p, 36)) // Read slot
        inputTokenAmount := calldataload(add(p, 68)) // Read slot
    }

    require(inputToken != address(0), "Invalid input token");
    require(outputToken != address(0), "Invalid output token");
    require(inputTokenAmount > 0, "Invalid token amount");
}
```


